from math import log
tr = [('pos', 'great phone love it'), ('pos', 'excellent battery great screen'), ('neg', 'terrible battery hate it'), ('neg', 'bad screen terrible')]
te = [('pos', 'love the screen'), ('neg', 'hate this bad phone'), ('pos', 'excellent phone'), ('neg', 'terrible screen')]
vocab = {w for _, t in tr for w in t.split()}
cnt = {'pos': {}, 'neg': {}}
for c, t in tr:
    for w in t.split():
        cnt[c][w] = cnt[c].get(w, 0) + 1
def sc(c, t):
    tot = sum(cnt[c].values())
    return log(0.5) + sum(log((cnt[c].get(w, 0) + 1) / (tot + len(vocab))) for w in t.split() if w in vocab)
pred = [max(cnt, key=lambda c: sc(c, t)) for _, t in te]
print(pred, sum(p == y for p, (y, _) in zip(pred, te)) / 4)

